// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { Toggle as TogglePrimitive } from "@/lib/primitives";
import { useShapedSheet } from "@/hooks/use-paper-object";
import type { Accent } from "@/lib/ink/paper/props";
import { bookmarkRecipe } from "@/lib/ink/recipes/bookmark-ink";
import { cn } from "@/lib/utils";
const RIBBON_TILT = "[&>svg]:[rotate:clamp(calc(var(--ll-tilt-max)*-1),var(--ll-tilt,0deg),var(--ll-tilt-max))]";
const RIBBON_SHADOW = "data-[state=on]:[&>svg]:[filter:var(--ll-drop-sticker)]";
const FORCED_ON = "forced-colors:data-[state=on]:bg-[Highlight]";
type BookmarkProps = UI.ComponentProps<typeof TogglePrimitive.Root> & {
  tone?: Accent;
  tilt?: boolean | number;
  seed?: string | number;
  size?: readonly [number, number];
};
const Bookmark = defineUi<BookmarkProps>("Bookmark", ["class", "style", "tone", "tilt", "seed", "size", "disabled"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const style = computed(() => _props["style"]);
  const children = renderValue(() => readSlot(_slots.default));
  const ref = computed(() => _props["ref"]);
  const tone = computed(() => _props["tone"] === undefined ? "tomato" as const : _props["tone"]);
  const tilt = computed(() => _props["tilt"]);
  const seed = computed(() => _props["seed"]);
  const size = computed(() => _props["size"]);
  const disabled = computed(() => _props["disabled"]);
  const props = computed(() => omitProps(_props, ["class", "style", "children", "ref", "tone", "tilt", "seed", "size", "disabled"]));
  const o = useShapedSheet(() => ({
    recipe: bookmarkRecipe,
    params: {
      tone: tone.value,
      mode: "toggle" as const,
      disabled: !!disabled.value
    },
    ref: ref.value as UI.Ref<HTMLElement>,
    seed: seed.value,
    tilt: tilt.value,
    tiltMax: 1.4,
    size: size.value,
    kind: "bookmark" as const
  }));
  return () => {
    return <TogglePrimitive.Root data-slot="bookmark" disabled={disabled.value} {...domProps(o.value.root)} {...domProps(props.value)} class={cn("relative isolate inline-block h-12 w-8 shrink-0 cursor-pointer align-top after:absolute after:-inset-1.5 disabled:cursor-not-allowed", RIBBON_TILT, RIBBON_SHADOW, FORCED_ON, className.value)} style={cssStyle({
      ...o.value.root.style,
      ...style.value
    })}>
      {o.value.node}
      <span class="sr-only">{readSlot(_slots.default) ?? "Bookmark"}</span>
    </TogglePrimitive.Root>;
  };
});
type BookmarkRibbonProps = UI.ComponentProps<"div"> & {
  tone?: Accent;
  tilt?: boolean | number;
  seed?: string | number;
  size?: readonly [number, number];
};
const BookmarkRibbon = defineUi<BookmarkRibbonProps>("BookmarkRibbon", ["class", "style", "tone", "tilt", "seed", "size"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const style = computed(() => _props["style"]);
  const ref = computed(() => _props["ref"]);
  const tone = computed(() => _props["tone"] === undefined ? "tomato" as const : _props["tone"]);
  const tilt = computed(() => _props["tilt"]);
  const seed = computed(() => _props["seed"]);
  const size = computed(() => _props["size"]);
  const props = computed(() => omitProps(_props, ["class", "style", "ref", "tone", "tilt", "seed", "size"]));
  const o = useShapedSheet(() => ({
    recipe: bookmarkRecipe,
    params: {
      tone: tone.value,
      mode: "static" as const,
      disabled: false
    },
    ref: ref.value as UI.Ref<HTMLElement>,
    seed: seed.value,
    tilt: tilt.value,
    tiltMax: 1.4,
    size: size.value,
    kind: "bookmark" as const
  }));
  return () => {
    return <div data-slot="bookmark-ribbon" aria-hidden="true" {...domProps(o.value.root)} {...domProps(props.value)} class={cn("pointer-events-none relative isolate inline-block h-14 w-8 shrink-0 [&>svg]:[filter:var(--ll-drop-sticker)]", RIBBON_TILT, className.value)} style={cssStyle({
      ...o.value.root.style,
      ...style.value
    })}>
      {o.value.node}
    </div>;
  };
});
export { Bookmark, BookmarkRibbon };
export type { BookmarkProps, BookmarkRibbonProps };

import { defineRecipe } from '@/lib/ink/recipes'
import { num, pathTag, tok } from '@/lib/ink/recipes/paper-set-ink'
import type { Accent } from '@/lib/ink/paper/props'
import { wash } from '@/lib/ink/fills'
import { densify } from '@/lib/ink/geom'
import type { Rng } from '@/lib/ink/rng'
import type { Pt } from '@/lib/ink/types'

export interface BookmarkParams {
  tone: Accent
  mode: 'toggle' | 'static'
  disabled: boolean
}

export const NOTCH = 0.55

export function ribbonPoly(w: number, h: number): Pt[] {
  const n = Math.min(h * 0.4, w * NOTCH)
  return [[0, 0], [w, 0], [w, h], [w / 2, h - n], [0, h]]
}

const ribbonD = (w: number, h: number, r: Rng) => {
  const p = densify([...ribbonPoly(w, h), ribbonPoly(w, h)[0]], 6).slice(0, -1)
  return `M${num(p[0][0])} ${num(p[0][1])}` + p.slice(1).map((q) => `L${num(q[0] + r.gauss(0, 0.22))} ${num(q[1] + r.gauss(0, 0.22))}`).join('') + 'z'
}

export const bookmarkRecipe = defineRecipe<BookmarkParams>({
  id: 'bookmark-ribbon',
  kind: 'bookmark',
  layers: ['rest', 'checked', 'disabled', 'hover'],
  pad: 6,
  draw(ink, { w, h }, { tone, mode, disabled }, ctx) {
    const d = ribbonD(w, h, ink.next('edge'))
    const ribbon = () => {
      const r = ink.next('cloth')
      const id = `ll-bm${ink.seed.toString(36)}`
      let s = `<clipPath id="${id}c"><path d="${d}"/></clipPath>`
      s += pathTag(d, { fill: tok(tone) })
      let g = ''
      for (let x = 2.2; x < w - 1; x += 2.3) g += `M${num(x + r.gauss(0, 0.08))} 0V${num(h)}`
      s += `<g clip-path="url(#${id}c)">`
      s += pathTag(g, { stroke: tok('ink'), sw: 0.7, op: 0.1 })
      s += pathTag(`M0 0H${num(w * 0.34)}V${num(h)}H0z`, { fill: tok('photo'), op: 0.22 })
      s += pathTag(`M${num(w * 0.7)} 0H${num(w)}V${num(h)}H${num(w * 0.7)}z`, { fill: tok('ink'), op: 0.13 })
      s += pathTag(`M0 ${num(h)}L${num(w / 2)} ${num(h - Math.min(h * 0.4, w * NOTCH))}L${num(w)} ${num(h)}V${num(h + 4)}H0z`, { fill: tok('ink'), op: 0.16 })
      s += `</g>`
      s += pathTag(`M2.6 1.5V${num(h - 3)}M${num(w - 2.6)} 1.5V${num(h - 3)}`, { stroke: tok('photo'), sw: 0.8, op: 0.6, extra: `stroke-dasharray="${num(r.range(2, 2.6))} ${num(r.range(1.5, 2.1))}"` })
      s += pathTag(d, { stroke: tok('ink'), sw: 0.7, op: 0.36 })
      return s
    }
    const ghost = (alpha: number) => {
      ink.raw(pathTag(d, { fill: tok('paper-shade'), op: alpha }) + pathTag(d, { stroke: tok('pencil'), sw: 1.1, op: 0.85, extra: 'stroke-dasharray="3.6 3.2"' }), 'under')
    }
    if (disabled) {
      ink.layer('disabled', () => ghost(0.3))
      return
    }
    if (mode === 'static') {
      ink.layer('rest', () => ink.raw(ribbon(), 'under'))
      return
    }
    ink.layer('rest', () => ghost(0.45))
    ink.layer('checked', () => ink.raw(ribbon(), 'under'))
    if (!ctx.calm) ink.layer('hover', () => wash(ink, ribbonPoly(w, h), tone, { alpha: 0.52, inset: 1.2 }))
  },
})
